CREATE OR REPLACE  VIEW PATRIMOINELIBCOMPLET ("ID", "IDOBJET", "IDTYPEPATRIMOINE", "REMARQUE", "ETATPATRIMOINE", "LIBELLE", "DESCRIPTION", "MONTANT", "OCCUPANT", "DEBUT_CONTRAT", "FIN_CONTRAT", "UTILISATION", "DEVISE", "COURS_CHANGE", "DATE_CHANGE", "VALTYPEPATRIMOINE", "DESCETYPEPATRIMOINE", "VALETATPATRIMOINE", "DESCEETATPATRIMOINE", "IDDEVISE", "VALDEVISE", "DESCEDEVISE", "CDCLT", "CDCAT", "NOMCLT", "ADRCLT", "NMSTTCLT", "TELCLT", "FAXCLT", "NMCIN", "NIF", "RC", "CATEGORIE", "DENOMINATION", "DATE_AQUISITION", "IDMARQUE", "PUISSANCE", "DETENTEUR", "MAINTENANCE", "IDTYPE_MATERIEL", "IMMATRICULATION", "ETAT", "VALMARQUE", "DESCEMARQUE", "VALTYPEMATERIEL", "DESCETYPEMATERIEL", "SUPERFICIE") AS 
 select
        p.ID,p.IDOBJET,p.IDTYPEPATRIMOINE,p.REMARQUE,p.ETAT as etatpatrimoine,p.LIBELLE,p.DESCRIPTION,p.MONTANT,p.OCCUPANT,p.DEBUT_CONTRAT,p.FIN_CONTRAT,p.UTILISATION,
        p.DEVISE, p.COURS_CHANGE, p.DATE_CHANGE,
        type.val as valtypepatrimoine, type.desce as descetypepatrimoine,
        etat.VAL as valetatpatrimoine, etat.DESCE as desceetatpatrimoine,
        dev.id as iddevise, dev.val as valdevise, dev.DESCE as descedevise,
        clt.CDCLT, CDCAT, NOMCLT, ADRCLT, NMSTTCLT, TELCLT, FAXCLT, NMCIN, NIF, RC, CATEGORIE,
        mat.DENOMINATION, DATE_AQUISITION, IDMARQUE, PUISSANCE, DETENTEUR, MAINTENANCE, IDTYPE_MATERIEL, IMMATRICULATION, mat.ETAT, VALMARQUE, DESCEMARQUE, VALTYPEMATERIEL, DESCETYPEMATERIEL,superficie
    from PATRIMOINE p
        LEFT join TYPEPATRIMOINE type on p.IDTYPEPATRIMOINE = type.ID
        LEFT join ETATPATRIMOINE etat on p.ETAT = etat.ID
        LEFT join V_CLIENT_CATEGORIE clt on clt.cdclt=p.occupant
        LEFT join DEVISEDEMAT dev on dev.ID=p.DEVISE
        left join MATERIELNAVALLIBCOMPLET mat on mat.id = p.IDOBJET;